function validate([ring, key]) {
  if (typeof ring !== 'string' || ring.length < 1 || ring.length > 100) return 'ring needs 1 to 100 characters.';
  if (typeof key !== 'string' || key.length < 1 || key.length > 100) return 'key needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(ring) || !/^[a-z]+$/.test(key)) return 'ring and key use only lowercase letters.';
  for (const ch of key) if (!ring.includes(ch)) return 'Every character of key must appear in ring.';
  return null;
}

