function findRotateSteps(ring, key) {
  const n = ring.length;
  const m = key.length;
  const positions = new Map();
  for (let j = 0; j < n; j++) {
    if (!positions.has(ring[j])) positions.set(ring[j], []);
    positions.get(ring[j]).push(j);
  }

  // dp[i][j]: fewest steps to enter key[i..] when ring[j] is under the marker.
  const dp = Array.from({ length: m + 1 }, () => new Array(n).fill(0));
  for (let i = m - 1; i >= 0; i--) {
    for (let j = 0; j < n; j++) {
      let best = Infinity;
      for (const target of positions.get(key[i])) {
        const gap = Math.abs(j - target);
        const turns = Math.min(gap, n - gap);
        best = Math.min(best, turns + 1 + dp[i + 1][target]);
      }
      dp[i][j] = best;
    }
  }
  return dp[0][0];
}

