function findRotateSteps(ring, key) {
  // Breadth-first search over (pointer, entered) states; every move costs exactly one step.
  const n = ring.length;
  const m = key.length;
  const seen = new Set(['0,0']);
  let frontier = [[0, 0]];
  let steps = 0;
  while (frontier.length) {
    const next = [];
    for (const [pos, done] of frontier) {
      if (done === m) return steps;
      const moves = [[(pos + 1) % n, done], [(pos + n - 1) % n, done]];
      if (ring[pos] === key[done]) moves.push([pos, done + 1]);
      for (const [p, d] of moves) {
        const id = p + ',' + d;
        if (!seen.has(id)) { seen.add(id); next.push([p, d]); }
      }
    }
    frontier = next;
    steps++;
  }
  return -1;
}

