function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = 1 + Math.floor(rand() * (size === 'large' ? 26 : 4));
  const ringLength = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 8);
  const keyLength = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  let ring = '';
  for (let j = 0; j < ringLength; j++) ring += letters[Math.floor(rand() * alphabet)];
  let key = '';
  for (let i = 0; i < keyLength; i++) key += ring[Math.floor(rand() * ringLength)];
  return [ring, key];
}
